import{_ as r,a0 as u,w as o,s,I as t,x as e,a1 as l,A as f,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法 | LCTT x X-CMD","titleTemplate":false,"description":"Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Libreoffice 4.1.1 Released, Install It On Ubuntu And Linux Mint","title":"Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法","tag":"201309","desc":""},"relativePath":"201309/Libreoffice 4.1.1 Released, Install It On Ubuntu And Linux Mint.md","filePath":"[post].md"}'),p={name:"201309/Libreoffice 4.1.1 Released, Install It On Ubuntu And Linux Mint.md"};function b(d,i,L,x,m,O){const n=u("Link");return o(),s("div",null,[i[13]||(i[13]=t("h1",{id:"libreoffice-4-1-1已發佈-及在ubuntu和linux-mint平台安裝方法",tabindex:"-1"},[e("Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法 "),t("a",{class:"header-anchor",href:"#libreoffice-4-1-1已發佈-及在ubuntu和linux-mint平台安裝方法","aria-label":"Permalink to “Libreoffice 4.1.1已發佈，及在Ubuntu和Linux Mint平台安裝方法”"},"​")],-1)),i[14]||(i[14]=t("p",null,"LibreOffice為您提供了六項功能豐富的應用程序以適合您的文檔和數據處理需要，它們包括：Writer、Calc、Impress、Draw、Math和Base。LibreOffice是什麼樣的軟件？我知道這個問題對於大多讀者是很容易回答的，但是隨着我們的愛好者與日俱增，我猜想有很多人並不瞭解Linux以及開源，所以我覺得我有必要提供一些有關LibreOffice的信息。",-1)),i[15]||(i[15]=t("p",null,"LibreOffice是一個運行在Linux、Windows和Mac操作系統的簡單而強大的開源軟件。有很多的志願者幫助完成LibreOffice這個項目，他們擔任着不同的角色，從工程任務到社區支持，還有創造性的工作。",-1)),i[16]||(i[16]=t("p",null,"下面是新聞播報：",-1)),t("p",null,[l(n,{href:"http://www.libreoffice.org/download/release-notes/"},{default:f(()=>[...i[0]||(i[0]=[e("LibreOffice 4.1.1",-1)])]),_:1}),i[1]||(i[1]=e(" 已經發布，這個版本有了很多的改進功能和錯誤修正。LibreOffice 4.1.1不再兼容老式的StarOffice(sun的office)的二進制文件，及不再輸出老式的Word和Excel文件。並解決了一個有趣的BUG —— fdo#67388 —— .deb包的文件屬主不再是 root:root 了。",-1))]),i[17]||(i[17]=a(`<p><strong>新特性和修復</strong></p><ul><li>關閉&#39;首頁相同內容&#39;的選項不再顯示在界面上</li><li>不能在Writer中選擇其它填充色 -&gt; Drawing 功能</li><li>REPORTBUILDER（報告生成器）：一些選項列表中的標籤顯示與功能不匹配</li><li>當檢查擴展更新時出現4.1段錯誤</li><li>FILESAVE: 保存為XLS文件格式遺漏保存cell表達式的公式的結果錯誤</li><li>字體樣式沒有儲存在ODG和ODP文件: 編輯一個樣式之後，關閉再打開，樣式會改變</li><li>不能保存新的自動更正詞條</li><li>MAILMERGE: 在LO 4.1.0.4中預先定義的標籤不包含格式信息</li><li>EDTING: BUG: calc 拼寫檢查崩潰.</li><li>在libvclplug_gtklo.so中被信號11(SIGSEGV)killed的soffice.bin發生段錯誤</li><li>GCJ Java Variant數據已知與LibreOffice有影響，我們建議使用OpenJDK來代替</li><li>LibreOffice 4.x 丟掉了一些長期棄用的功能，其中包括對老式的StarOffice二進制文件的支持、導出老式的Word和Excel（6.0/95版本）以及老式的ODMA文檔管理</li><li>已更改或添加了一些菜單項。如果你丟失了一些東西，可能是由於你使用了以前的LibreOffice安裝中的定製菜單設置.</li></ul><p>那LibreOffice 4.1.1怎樣安裝呢？打開終端並複製以下命令，這樣就可以把LibreOffice安裝到Ubuntu或Linux Mint。</p><pre><code>$ sudo add-apt-repository ppa:libreoffice/libreoffice-4-1

$ sudo apt-get update

$ sudo apt-get install libreoffice
</code></pre>`,4)),t("p",null,[i[3]||(i[3]=e("via: ",-1)),l(n,{href:"http://www.unixmen.com/libreoffice-4-1-1-released-install-ubuntu-linux-mint/"},{default:f(()=>[...i[2]||(i[2]=[e("http://www.unixmen.com/libreoffice-4-1-1-released-install-ubuntu-linux-mint/",-1)])]),_:1})]),t("p",null,[i[6]||(i[6]=e("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:f(()=>[...i[4]||(i[4]=[e("LCTT",-1)])]),_:1}),i[7]||(i[7]=e(" 原創翻譯，",-1)),l(n,{href:"http://linux.cn/portal.php"},{default:f(()=>[...i[5]||(i[5]=[e("Linux中國",-1)])]),_:1}),i[8]||(i[8]=e(" 榮譽推出",-1))]),t("p",null,[i[11]||(i[11]=e("譯者：",-1)),l(n,{href:"http://linux.cn/space/flsf01"},{default:f(()=>[...i[9]||(i[9]=[e("flsf01",-1)])]),_:1}),i[12]||(i[12]=e(" 校對：",-1)),l(n,{href:"http://linux.cn/space/14763"},{default:f(()=>[...i[10]||(i[10]=[e("Caroline",-1)])]),_:1})])])}const I=r(p,[["render",b]]);export{C as __pageData,I as default};
